  /// Index of an element, or nullopt if the symbol is not in the list.
  ///
  /// The found/not-found bit is part of the contract, not a convenience:
  /// upstream ASSIGNS a known element's count and ACCUMULATES an unknown
  /// one into the '?' slot, so a caller that cannot tell them apart gets
  /// one of the two cases wrong. Returning the '?' index for both made
  /// two unknown symbols in one formula collapse to the last.
  inline constexpr std::optional<std::size_t>
  peptDeepElementIndex(std::string_view symbol)
  {
    for (std::size_t i = 0; i < PEPTDEEP_MOD_ELEMENTS.size(); ++i)
    {
      if (PEPTDEEP_MOD_ELEMENTS[i] == symbol) { return i; }
    }
    return std::nullopt;
  }

  /// The '?' catch-all slot, where unknown elements accumulate.
  inline constexpr std::size_t PEPTDEEP_UNKNOWN_ELEMENT =
    PEPTDEEP_MOD_ELEMENTS.size() - 1;

